mapper.select:
SELECT ENTRUST_ID as closeId,ps as ps FROM ETR_ENTRUST WHERE ENTRUST_ID IN ( SELECT ENTRUST_ID FROM ETR_ENTRUST WHERE ENTRUST_STATUS IN ( #{ENTRUST_STATUS_01}, #{ENTRUST_STATUS_02}, #{ENTRUST_STATUS_03}, #{ENTRUST_STATUS_05},#{ENTRUST_STATUS_08},#{ENTRUST_STATUS_07} )
AND MDATE <= TO_DATE(#{sysDate},'YYYY-MM-DD')
)

mapper.update:
UPDATE ETR_ENTRUST SET ENTRUST_STATUS = '06' WHERE ENTRUST_ID IN ( SELECT ENTRUST_ID FROM ETR_ENTRUST WHERE ENTRUST_STATUS IN ( #{ENTRUST_STATUS_01}, #{ENTRUST_STATUS_02}, #{ENTRUST_STATUS_03}, #{ENTRUST_STATUS_05},#{ENTRUST_STATUS_08},#{ENTRUST_STATUS_07} )
AND MDATE <= TO_DATE(#{sysDate},'YYYY-MM-DD')
)

UPDATE ETR_DISTRIBUTE SET REC_STATUS = '06' WHERE ENTRUST_ID IN ( SELECT ENTRUST_ID FROM ETR_ENTRUST WHERE ENTRUST_STATUS IN ( #{ENTRUST_STATUS_01}, #{ENTRUST_STATUS_02}, #{ENTRUST_STATUS_03}, #{ENTRUST_STATUS_05},#{ENTRUST_STATUS_08},#{ENTRUST_STATUS_07})
AND MDATE <= TO_DATE(#{sysDate},'YYYY-MM-DD')
)
